import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"19、【临】 兑下坤上","description":"周易尚氏学 - 19、【临】 兑下坤上","frontmatter":{"title":"19、【临】 兑下坤上","description":"周易尚氏学 - 19、【临】 兑下坤上"},"headers":[],"relativePath":"zh/classics/shangshi/024.md","filePath":"zh/classics/shangshi/024.md"}'),h={name:"zh/classics/shangshi/024.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_19、【临】-兑下坤上" tabindex="-1">19、【临】 兑下坤上 <a class="header-anchor" href="#_19、【临】-兑下坤上" aria-label="Permalink to “19、【临】 兑下坤上”">​</a></h1><p>释诂。临视也。毁梁哀七年。有临天下之言焉。注。临抚有之也。卦以震君临四阴。正抚有也。故曰临。临辟丑。阳息卦。故曰元亨。左传云。不行之谓临。行而不已。则至八月而凶矣。故又曰利贞。言利于贞定也。月卦始子复。至未遁正八月。故郑陆虞皆以八月为遁。而虞氏以杀君父说凶义则非。杀君父皆否遁所同有。胡独八月凶乎。按易林恒之临云。神之在丑。破逆为咎。不利西南。商人休止。临辟丑。震为神。故曰神之在丑。乃行至未而破丑。故曰破逆为咎。又按汉书翼奉传。平昌侯三来见臣。皆以正日加邪时。孟康曰。谓乙丑之日。丑为正。日加未而来。未破丑。故曰邪时。陆绩易传至于八月凶注曰。建丑至未也。八遁亦以未破丑说凶义。徒以弒君父为说。何以辞于其它消卦乎。几易言八月七日。皆言爻数。后儒往往以殷正周正为说。皆梦吃语也。</p><p>彖曰。临。刚来浸而长。说而顺。刚中而应。大亨以正。天之道也。至于八月有凶。消不久也。</p><p>通消卦。故曰不久。</p><p>象曰。泽上有地。临。君子以教思无穷。容保民无疆。</p><p>震兑皆为言。故曰教思无穷。坤为民。震为仁。故曰容保民。坤广大。故曰无疆。</p><p>初九。咸临。贞吉。</p><p>咸感也。初二爻皆有应。故皆曰咸临。贞卜问也。</p><h3 id="象曰。咸临贞吉。志行正也。" tabindex="-1">象曰。咸临贞吉。志行正也。 <a class="header-anchor" href="#象曰。咸临贞吉。志行正也。" aria-label="Permalink to “象曰。咸临贞吉。志行正也。”">​</a></h3><p>坤为志。应在坤。皆当位。故曰志行正。</p><p>九二。成临。吉。无不利。</p><p>承遇阴则通。故曰无不利。</p><h3 id="象曰。咸临吉无不利。未顺命也。" tabindex="-1">象曰。咸临吉无不利。未顺命也。 <a class="header-anchor" href="#象曰。咸临吉无不利。未顺命也。" aria-label="Permalink to “象曰。咸临吉无不利。未顺命也。”">​</a></h3><p>二必升五。得尚于中行。而卦以不利为义。故曰未顺命。</p><p>六三。甘临。无攸利。既忧之。无咎。</p><p>说文。甘美也。三独近二。阴顺阳。言甘于顺二也。然不当位。无应。故无所利。坤为忧。知无所利而优之。故无咎也。</p><h3 id="象曰。甘临。位不当也。既忧之。咎不长也。" tabindex="-1">象曰。甘临。位不当也。既忧之。咎不长也。 <a class="header-anchor" href="#象曰。甘临。位不当也。既忧之。咎不长也。" aria-label="Permalink to “象曰。甘临。位不当也。既忧之。咎不长也。”">​</a></h3><p>不长谓不久。</p><p>六四。至临。无咎。</p><p>虞翻曰。至下也。谓下应初。当位有实。故无咎。</p><h3 id="象曰。至临无咎。" tabindex="-1">象曰。至临无咎。 <a class="header-anchor" href="#象曰。至临无咎。" aria-label="Permalink to “象曰。至临无咎。”">​</a></h3><p>位当也。</p><p>六五。知临。大君之宜。吉。</p><p>知音智。言宜知几也。震为大君。象失传。详焦氏易诂九二震主交。应在五。二五相上下。皆当位。故曰大君之宜。言二宜升五也。</p><h3 id="象曰。大君之宜。行中之谓也。" tabindex="-1">象曰。大君之宜。行中之谓也。 <a class="header-anchor" href="#象曰。大君之宜。行中之谓也。" aria-label="Permalink to “象曰。大君之宜。行中之谓也。”">​</a></h3><p>二五皆中位。故曰行中。知临者。言宜知几。与二相上下也。</p><p>上六。敦临。吉。无咎。</p><p>阳息即至三。上稍止即有应。故曰敦临。敦与屯与顿皆通。有止意待意。义详复卦。言稍待即有应。故曰志在内。内谓三也。故复五六亦曰敦复。言五少迟。阳即息至二。有应。与此同也。旧解训敦为厚。非。</p><h3 id="象曰。敦临之吉。" tabindex="-1">象曰。敦临之吉。 <a class="header-anchor" href="#象曰。敦临之吉。" aria-label="Permalink to “象曰。敦临之吉。”">​</a></h3><p>志在内也言顿止之故。因阳息即至三。有应也。易之道贵将来。将来有应。故吉。不然内无应。何吉之有。凡云志在内。志在外者。皆谓应爻。九家谓志在二升五。清儒皆宗之。由误解敦字故也。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
